/// Sends `request` and checks the status. The `url` is returned for error
/// messages.
pub async fn execute(
    transport: &(impl Transport + ?Sized),
    request: Request,
) -> Result<(String, HttpResponse), ApiError> {
    let mut request = request.build()?;
    config::prepare(&mut request);
    let url = request.url.clone();
    let response = transport
        .send(request)
        .await
        .map_err(|error| ApiError::Network {
            url: url.clone(),
            reason: error.to_string(),
        })?;
    if !response.is_success() {
        let message = config::error_message(&response);
        return Err(ApiError::Http {
            url,
            status: response.status,
            message,
            body: response.body,
        });
    }
    Ok((url, response))
}

/// Sends `request` and decodes the JSON body as `T` (after
/// `config::unwrap_body`).
pub async fn send_json<T: json::Decode>(
    transport: &(impl Transport + ?Sized),
    request: Request,
) -> Result<T, ApiError> {
    let (url, response) = execute(transport, request).await?;
    decode_body(&url, &response.body)
}

/// Decodes a JSON body the way [`send_json`] does: for responses saved to
/// disk, tests and fixtures.
pub fn decode_body<T: json::Decode>(url: &str, body: &[u8]) -> Result<T, ApiError> {
    let decode_error = |reason: String| ApiError::Decode {
        url: url.to_owned(),
        reason,
    };
    let value: Value = if body.iter().all(u8::is_ascii_whitespace) {
        Value::Null
    } else {
        serde_json::from_slice(body).map_err(|error| {
            if body.trim_ascii_start().starts_with(b"<") {
                decode_error("the body is HTML, not JSON".to_owned())
            } else {
                decode_error(error.to_string())
            }
        })?
    };
    json::decode(config::unwrap_body(value)).map_err(decode_error)
}

pub async fn send_text(
    transport: &(impl Transport + ?Sized),
    request: Request,
) -> Result<String, ApiError> {
    let (url, response) = execute(transport, request).await?;
    String::from_utf8(response.body).map_err(|error| ApiError::Decode {
        url,
        reason: format!("the body is not UTF-8: {error}"),
    })
}

pub async fn send_bytes(
    transport: &(impl Transport + ?Sized),
    request: Request,
) -> Result<Vec<u8>, ApiError> {
    let (_, response) = execute(transport, request).await?;
    Ok(response.body)
}

pub async fn send_empty(
    transport: &(impl Transport + ?Sized),
    request: Request,
) -> Result<(), ApiError> {
    execute(transport, request).await.map(|_| ())
}

