/// How arrays are written in query strings and forms.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ArrayFormat {
    /// `ids=1&ids=2` (OpenAPI's default, `style: form, explode: true`).
    Repeat,
    /// `ids[0]=1&ids[1]=2` (what `qs.stringify` sends by default).
    Indices,
    /// `ids[]=1&ids[]=2`.
    Brackets,
    /// `ids=1,2`.
    Comma,
}

/// The `name=value` pairs of a serialized parameters struct. Nested objects
/// use brackets (`filter[color]=red`); `null` values are skipped.
pub fn query_pairs(value: &Value, format: ArrayFormat) -> Vec<(String, String)> {
    let mut pairs = Vec::new();
    if let Value::Object(map) = value {
        for (key, value) in map {
            push_pairs(&mut pairs, key.clone(), value, format);
        }
    }
    pairs
}

fn push_pairs(pairs: &mut Vec<(String, String)>, key: String, value: &Value, format: ArrayFormat) {
    match value {
        Value::Null => {}
        Value::Bool(b) => pairs.push((key, b.to_string())),
        Value::Number(n) => pairs.push((key, n.to_string())),
        Value::String(s) => pairs.push((key, s.clone())),
        Value::Array(items) => match format {
            ArrayFormat::Comma => {
                let joined: Vec<String> = items.iter().filter_map(scalar_text).collect();
                if !joined.is_empty() {
                    pairs.push((key, joined.join(",")));
                }
            }
            _ => {
                for (index, item) in items.iter().enumerate() {
                    let item_key = match format {
                        ArrayFormat::Repeat => key.clone(),
                        ArrayFormat::Indices => format!("{key}[{index}]"),
                        _ => format!("{key}[]"),
                    };
                    push_pairs(pairs, item_key, item, format);
                }
            }
        },
        Value::Object(map) => {
            for (child, value) in map {
                push_pairs(pairs, format!("{key}[{child}]"), value, format);
            }
        }
    }
}

fn scalar_text(value: &Value) -> Option<String> {
    match value {
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => Some(n.to_string()),
        Value::Bool(b) => Some(b.to_string()),
        _ => None,
    }
}

fn header_value(value: &Value) -> Option<String> {
    match value {
        Value::Null => None,
        Value::Array(items) => Some(
            items
                .iter()
                .filter_map(scalar_text)
                .collect::<Vec<_>>()
                .join(","),
        ),
        Value::Object(_) => Some(value.to_string()),
        other => scalar_text(other),
    }
}

/// `a=1&b=x%20y`.
pub fn encode_pairs(pairs: &[(String, String)]) -> String {
    let mut out = String::new();
    for (index, (key, value)) in pairs.iter().enumerate() {
        if index > 0 {
            out.push('&');
        }
        out.push_str(&encode_component(key));
        out.push('=');
        out.push_str(&encode_component(value));
    }
    out
}

/// Percent-encodes everything but RFC 3986's unreserved characters.
pub fn encode_component(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for byte in text.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(byte as char)
            }
            _ => out.push_str(&format!("%{byte:02X}")),
        }
    }
    out
}

/// A path parameter's value, percent-encoded. Arrays are comma separated.
pub fn path_param(value: &impl Serialize) -> String {
    let text = match serde_json::to_value(value) {
        Ok(Value::Array(items)) => items
            .iter()
            .filter_map(scalar_text)
            .collect::<Vec<_>>()
            .join(","),
        Ok(Value::Object(_)) | Ok(Value::Null) | Err(_) => String::new(),
        Ok(other) => scalar_text(&other).unwrap_or_default(),
    };
    encode_component(&text)
}

