/// A file in a `multipart/form-data` body.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct FilePart {
    pub file_name: String,
    /// `application/octet-stream` when empty.
    pub content_type: String,
    pub bytes: Vec<u8>,
}

impl FilePart {
    pub fn new(
        file_name: impl Into<String>,
        content_type: impl Into<String>,
        bytes: Vec<u8>,
    ) -> Self {
        Self {
            file_name: file_name.into(),
            content_type: content_type.into(),
            bytes,
        }
    }
}

/// Serialized as its file name and size, so a body with files can still be
/// logged or used as a key.
impl Serialize for FilePart {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeStruct as _;
        let mut file = serializer.serialize_struct("FilePart", 2)?;
        file.serialize_field("file_name", &self.file_name)?;
        file.serialize_field("size", &self.bytes.len())?;
        file.end()
    }
}

/// A `multipart/form-data` body being written.
#[derive(Debug, Clone)]
pub struct Multipart {
    boundary: String,
    body: Vec<u8>,
}

impl Default for Multipart {
    fn default() -> Self {
        Self::new()
    }
}

impl Multipart {
    pub fn new() -> Self {
        use std::sync::atomic::{AtomicU64, Ordering};
        static COUNTER: AtomicU64 = AtomicU64::new(0);
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or_default();
        let count = COUNTER.fetch_add(1, Ordering::Relaxed);
        Self {
            boundary: format!("----swagger-rust-{nanos:x}{count:x}"),
            body: Vec::new(),
        }
    }

    fn part_header(&mut self, name: &str, file_name: Option<&str>, content_type: Option<&str>) {
        self.body
            .extend_from_slice(format!("--{}\r\n", self.boundary).as_bytes());
        let name = name.replace('"', "%22");
        match file_name {
            Some(file_name) => {
                let file_name = file_name.replace('"', "%22");
                self.body.extend_from_slice(
                    format!("Content-Disposition: form-data; name=\"{name}\"; filename=\"{file_name}\"\r\n").as_bytes(),
                );
            }
            None => self.body.extend_from_slice(
                format!("Content-Disposition: form-data; name=\"{name}\"\r\n").as_bytes(),
            ),
        }
        if let Some(content_type) = content_type {
            self.body
                .extend_from_slice(format!("Content-Type: {content_type}\r\n").as_bytes());
        }
        self.body.extend_from_slice(b"\r\n");
    }

    /// A scalar field (string, number, boolean, enum) as text.
    pub fn text(&mut self, name: &str, value: &impl Serialize) {
        let text = match serde_json::to_value(value) {
            Ok(Value::String(s)) => s,
            Ok(Value::Null) => return,
            Ok(other) => other.to_string(),
            Err(_) => return,
        };
        self.part_header(name, None, None);
        self.body.extend_from_slice(text.as_bytes());
        self.body.extend_from_slice(b"\r\n");
    }

    /// An object or array field, as JSON.
    pub fn json(&mut self, name: &str, value: &impl Serialize) {
        if let Ok(bytes) = serde_json::to_vec(value) {
            self.part_header(name, None, Some("application/json"));
            self.body.extend_from_slice(&bytes);
            self.body.extend_from_slice(b"\r\n");
        }
    }

    pub fn file(&mut self, name: &str, file: &FilePart) {
        let content_type = if file.content_type.is_empty() {
            "application/octet-stream"
        } else {
            file.content_type.as_str()
        };
        let file_name = if file.file_name.is_empty() {
            name
        } else {
            file.file_name.as_str()
        };
        self.part_header(name, Some(file_name), Some(content_type));
        self.body.extend_from_slice(&file.bytes);
        self.body.extend_from_slice(b"\r\n");
    }

    /// The `Content-Type` header and the body.
    pub fn finish(mut self) -> (String, Vec<u8>) {
        self.body
            .extend_from_slice(format!("--{}--\r\n", self.boundary).as_bytes());
        (
            format!("multipart/form-data; boundary={}", self.boundary),
            self.body,
        )
    }
}
